package local.investment.personal;

import android.util.Log;
import androidx.test.core.app.ActivityScenario;
import local.investment.personal.ReportRevisitPage.Check;
import local.investment.personal.ReportRevisitPage.Script;

/** Requires the whole readout above fixed navigation and text inside its actual table cells. */
final class PortfolioCompositionFrameEvidence {
    record Request(ActivityScenario<MainActivity> scenario, ReportRevisitPage page) {}
    private final Request request;
    PortfolioCompositionFrameEvidence(Request request) { this.request=request; }
    private static final String COMMON="\nfunction finiteRect(r){return [r.left,r.right,r.top,r.bottom,r.width,r.height].every(Number.isFinite)&&r.width>0&&r.height>0;}\nfunction inside(r,b){return r.left>=b.left&&r.right<=b.right&&r.top>=b.top&&r.bottom<=b.bottom;}\nfunction usableViewport(v){\n const bounds={left:v.offsetLeft,right:v.offsetLeft+v.width,top:v.offsetTop,bottom:v.offsetTop+v.height,navigationTop:null};\n const navigation=document.querySelector('.managed-navigation');\n if(navigation&&navigation.checkVisibility({checkOpacity:true,checkVisibilityCSS:true})&&getComputedStyle(navigation).position==='fixed'){\n  const r=navigation.getBoundingClientRect();if(finiteRect(r)&&r.bottom>bounds.top&&r.top<bounds.bottom){bounds.bottom=Math.min(bounds.bottom,r.top);bounds.navigationTop=r.top;}\n }\n return bounds;\n}\nfunction measureReadout(){\n const section=document.querySelector('#portfolio-close-composition'),view=visualViewport;if(!section||!view)return null;\n const parts=[section.querySelector('h3'),section.querySelector(':scope > p'),section.querySelector(':scope > dl'),section.querySelector('.portfolio-composition-table')];if(parts.some(e=>!e))return null;\n const rects=parts.map(e=>e.getBoundingClientRect()),union={left:Math.min(...rects.map(r=>r.left)),right:Math.max(...rects.map(r=>r.right)),top:Math.min(...rects.map(r=>r.top)),bottom:Math.max(...rects.map(r=>r.bottom))};union.height=union.bottom-union.top;\n return {section,view,parts,union,usable:usableViewport(view)};\n}\nfunction closedDisclosureBodyText(node){\n for(let parent=node.parentElement;parent;parent=parent.parentElement){\n  if(parent.tagName==='DETAILS'&&!parent.open){const summary=[...parent.children].find(child=>child.tagName==='SUMMARY');if(!summary||!summary.contains(node))return true;}\n }\n return false;\n}\nfunction textProblems(element,bounds){\n const owner=element.closest('th,td')||element,cell=owner.getBoundingClientRect(),walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT),problems=[];let node,visible=false;\n const strict=element.tagName==='SUMMARY'||element.tagName==='SMALL'||element.matches('[data-composition-value],[data-composition-share],th[scope=col]');\n while((node=walker.nextNode())){\n  if(!node.textContent.trim()||closedDisclosureBodyText(node))continue;const range=document.createRange();range.selectNodeContents(node);const rects=[...range.getClientRects()].filter(r=>r.width!==0&&r.height!==0);\n  if(strict&&rects.length===0)problems.push({type:'required_text_not_rendered',tag:element.tagName});\n  for(const r of rects){visible=true;if(!finiteRect(r)||!inside(r,cell)||!inside(r,bounds))problems.push({type:'text_outside_cell_or_usable_bounds',tag:element.tagName,text:node.textContent.trim().slice(0,80),textRect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom},cellRect:{left:cell.left,right:cell.right,top:cell.top,bottom:cell.bottom}});}\n }\n if(!visible)problems.push({type:'required_text_not_rendered',tag:element.tagName});return problems;\n}\nfunction readoutProblems(g){\n if(!g)return [{type:'missing_readout'}];const {section:s,usable:u,union,parts}=g,problems=[];\n if(![u.left,u.right,u.top,u.bottom,union.top,union.bottom,union.height].every(Number.isFinite)||u.bottom<=u.top||union.height>u.bottom-u.top)problems.push({type:'complete_readout_exceeds_usable_height',readoutHeight:union.height,usableHeight:u.bottom-u.top});\n const summaries=[...s.querySelectorAll('tr[data-listing-id] summary')],confirmations=[...s.querySelectorAll('tr[data-listing-id] small')];\n if(summaries.length!==2||confirmations.length!==2||s.querySelectorAll('[data-composition-value]').length!==3||s.querySelectorAll('[data-composition-share]').length!==3||s.querySelectorAll('tr[data-composition-cash]').length!==1)problems.push({type:'complete_readout_elements_missing'});\n if(summaries.length===2&&(!summaries[0].textContent.includes('ZERO')||!summaries[0].textContent.includes('Class A')||!summaries[0].textContent.includes('Zero Company')||!summaries[1].textContent.includes('ZERO.C')||!summaries[1].textContent.includes('Class C')||!summaries[1].textContent.includes('Zero Company')))problems.push({type:'exact_identity_summary_missing'});\n const elements=[...parts.slice(0,3),...s.querySelectorAll('table th,table td,tr[data-listing-id] summary,tr[data-listing-id] small,tr[data-composition-cash] small')];\n for(const e of elements){const r=e.getBoundingClientRect();if(!e.checkVisibility({checkOpacity:true,checkVisibilityCSS:true})||!finiteRect(r)||!inside(r,u))problems.push({type:'required_element_outside_usable_bounds',tag:e.tagName,rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom}});problems.push(...textProblems(e,u));}\n return problems;\n}\n";
    private static final String POSITION="(()=>{"+COMMON+"\n let g=measureReadout();if(!g)return JSON.stringify({problemCount:1,problems:[{type:'missing_readout'}]});\n const target=g.usable.top+Math.max(0,(g.usable.bottom-g.usable.top-g.union.height)/2);window.scrollBy({top:g.union.top-target,behavior:'instant'});\n g=measureReadout();const problems=readoutProblems(g);return JSON.stringify({viewport:{top:g.view.offsetTop,bottom:g.view.offsetTop+g.view.height,width:g.view.width,height:g.view.height},usable:g.usable,readout:g.union,problemCount:problems.length,problems:problems.slice(0,2)});\n})()";
    private static final String READY="(()=>{"+COMMON+"function legacyFrameReady(s,v){const r=s.getBoundingClientRect(),a=s.querySelector('h3').getBoundingClientRect(),b=s.querySelector('.portfolio-composition-table').getBoundingClientRect(),w=document.documentElement.clientWidth;return w===412 && document.documentElement.scrollWidth<=w+1 && s.checkVisibility() && [r.left,r.right,r.top,r.bottom,v.width,v.height].every(Number.isFinite) && r.left>=v.offsetLeft && r.right<=v.offsetLeft+v.width && a.top>=v.offsetTop && b.bottom<=v.offsetTop+v.height && s.querySelector('[role=region]')?.tabIndex===0 && [...s.querySelectorAll('[data-composition-value],[data-composition-share],th[scope=col]')].every(e=>{const b=e.getBoundingClientRect();return e.checkVisibility() && b.left>=v.offsetLeft && b.right<=v.offsetLeft+v.width;});}\n\n const g=measureReadout();return g!==null&&legacyFrameReady(g.section,g.view)&&readoutProblems(g).length===0;\n})()";
    void retain() throws Exception {
        ReportRevisitPage page=request.page();
        String measurement=page.read(new Script(POSITION));
        Log.i("CompositionFrameGeometry",measurement);
        page.await(new Check("complete composition heading, dates, denominator and every value/percentage fit the native frame",new Script(READY)).nativeReady());
        new PortfolioReportFrameCapture(new PortfolioReportFrameCapture.Request(request.scenario(),PortfolioReportFrameCapture.Frame.COMPOSITION)).retain();
    }
}
